mapper.select:
SELECT a.NATIONAL_DEBT_ID, b.GUOKU_ID, b.GUOKU_PID, b.GUOKU_DSCR, b.LEVEL, CONCAT(b.isleaf,'') AS isleaf, a.CHECK_DATE, a.CHECK_COUNT, a.SUMMARY_STATE FROM inspection.inspection_national_debt a LEFT JOIN dmcode.cm_guoku_dimnsn b ON a.CHECK_GK=b.GUOKU_ID WHERE 1=1
AND a.NATIONAL_DEBT_ID IN(SELECT NATIONAL_DEBT_ID FROM inspection.inspection_national_debt WHERE PARENT_GK = #{params.parentId} AND SUMMARY_STATE = '2')
AND a.CHECK_DATE = #{params.CHECK_DATE}
AND a.CHECK_GK = #{params.CURRENT_GK}
AND a.NATIONAL_DEBT_ID IN
#{item}
ORDER BY a.CHECK_DATE DESC

SELECT CASE WHEN LEVEL = 2 THEN
            CASE WHEN ${params.GUOKU_ID} = ${params.CURRENT_GK} THEN
                (SELECT GROUP_CONCAT(IFNULL(NATIONAL_DEBT_ID,'')) FROM inspection.inspection_national_debt
                WHERE

                    PARENT_GK = #{params.GUOKU_ID}


                    CHECK_GK = #{params.GUOKU_ID}



                    AND CHECK_DATE = #{params.CHECK_DATE}

                )
            ELSE
                (SELECT CASE WHEN LEVEL = 3 THEN
                            (SELECT GROUP_CONCAT(IFNULL(NATIONAL_DEBT_ID,'')) FROM inspection.inspection_national_debt
                            WHERE SUMMARY_STATE = '2' AND CHECK_GK = #{params.GUOKU_ID}

                                AND CHECK_DATE = #{params.CHECK_DATE}

                            )
                        ELSE
                            (SELECT GROUP_CONCAT(IFNULL(t.NATIONAL_DEBT_ID,'')) FROM inspection.inspection_national_debt t
                            RIGHT JOIN
                            (
                            SELECT CASE WHEN d.SUMMARY_STATE ='2' THEN d.NATIONAL_DEBT_ID END AS NATIONAL_DEBT_ID,d.CHECK_DATE
                            FROM inspection.inspection_national_debt d
                            WHERE CHECK_GK = (
                                            SELECT DISTINCT PARENT_GK FROM inspection.inspection_national_debt WHERE SUMMARY_STATE = '2' and CHECK_GK = #{params.GUOKU_ID}

                                                AND CHECK_DATE = #{params.CHECK_DATE}

                                            )
                            ) v ON t.CHECK_DATE=v.CHECK_DATE AND v.NATIONAL_DEBT_ID IS NOT NULL
                            WHERE t.CHECK_GK = #{params.GUOKU_ID}

                                AND t.CHECK_DATE = #{params.CHECK_DATE}

                            )
                        END
                FROM dmcode.cm_guoku_dimnsn WHERE GUOKU_ID = #{params.GUOKU_ID})
            END
     WHEN LEVEL = 3 THEN
        (SELECT GROUP_CONCAT(IFNULL(NATIONAL_DEBT_ID,'')) FROM inspection.inspection_national_debt
        WHERE SUMMARY_STATE = '2' AND CHECK_GK = #{params.GUOKU_ID} AND PARENT_GK = #{params.CURRENT_GK}

            AND CHECK_DATE = #{params.CHECK_DATE}

        )
     ELSE
        (SELECT GROUP_CONCAT(IFNULL(NATIONAL_DEBT_ID,'')) FROM inspection.inspection_national_debt WHERE CHECK_GK = #{params.GUOKU_ID}

            AND CHECK_DATE = #{params.CHECK_DATE}

        )
     END AS GUOKU_ID
FROM dmcode.cm_guoku_dimnsn WHERE GUOKU_ID = #{params.CURRENT_GK}

SELECT NATIONAL_DEBT_ID,CHECK_GK,PARENT_GK,CHECK_DATE,CHECK_COUNT,SUMMARY_STATE
FROM inspection.inspection_national_debt
WHERE 1=1

    AND PARENT_GK = #{params.parentId}


    AND CHECK_DATE = #{params.CHECK_DATE}


    AND SUMMARY_STATE = #{params.SUMMARY_STATE}

SELECT * FROM inspection.inspection_national_debt
WHERE CHECK_DATE = #{params.CHECK_DATE} AND CHECK_GK IN

    #{guokuId}

SELECT PROJECT_ID,NATIONAL_DEBT_ID,ITEM_ID,BANK_CODE,SCORE,CHECK_DATE,CHECK_COUNT
FROM inspection.inspection_project_rate
WHERE NATIONAL_DEBT_ID = #{params.NATIONAL_DEBT_ID}
AND CHECK_DATE = #{params.CHECK_DATE}

    AND CHECK_COUNT = #{params.CHECK_COUNT}

SELECT ITEM_ID,BANK_CODE
FROM inspection.inspection_project_rate
WHERE CHECK_DATE = #{params.CHECK_DATE}
AND CHECK_GK IN

    #{guokuId}

AND ITEM_ID IN

    #{itemId}

GROUP BY BANK_CODE,ITEM_ID

SELECT PROJECT_ID,NATIONAL_DEBT_ID,ITEM_ID,BANK_CODE,SCORE,CHECK_DATE
FROM inspection.inspection_project_summary
WHERE NATIONAL_DEBT_ID = #{params.NATIONAL_DEBT_ID} AND CHECK_DATE = #{params.CHECK_DATE}

SELECT GUOKU_ID,GUOKU_DSCR,GUOKU_SHUXING_ID,GUOKU_SHUXING_DSCR,GUOKU_PID,
    LEVEL,LEVEL_DSCR,AREA_NO_ID,AREA_DSCR,BOOKORGCODE,BOOKORGNAME
    FROM dmcode.cm_guoku_dimnsn
    WHERE GUOKU_ID  = (
        SELECT CHECK_GK FROM inspection.inspection_national_debt WHERE NATIONAL_DEBT_ID = #{params.NATIONAL_DEBT_ID}
    )

SELECT MAX(CHECK_COUNT) AS CHECK_COUNT,GROUP_CONCAT(CHECK_GK) AS CHECK_GK FROM
inspection.inspection_national_debt
WHERE CHECK_DATE = #{params.CHECK_DATE}


    AND (CHECK_GK = #{params.GUOKU_ID} OR SUMMARY_STATE = '2' AND PARENT_GK = #{params.GUOKU_ID}
    OR CHECK_GK IN (SELECT CHECK_GK FROM inspection.inspection_national_debt
    WHERE PARENT_GK IN (SELECT CHECK_GK FROM inspection.inspection_national_debt
    WHERE PARENT_GK = #{params.GUOKU_ID}))
    )



    AND (CHECK_GK = #{params.GUOKU_ID} OR SUMMARY_STATE = '2' AND PARENT_GK = #{params.GUOKU_ID})



    AND CHECK_GK = #{params.GUOKU_ID}
